-- APPLIED RECEIPT: DO NOT RERUN. Explicit organiser approval, 25 October 2026.
-- Monday Division A, 2026 - Season 2 only. Distinct new Jaghori FC/green;
-- Declan -> Jaghori and Gay Guys -> reinstated Buckle: two results each.
-- Imole's former Buckle result stays with Imole. No scores/IDs/history deleted.
-- Future fixtures MUST use the separate reviewed admin import, not this file.
BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
LOCK TABLE public.teams,public.fixtures,public.result_versions,public.standing_adjustments,public.team_kickoff_preferences,public.team_fixture_notes IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND season_id='ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Competition state changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.teams WHERE id='0ad2ddbd-80e1-40f5-bb80-2e756a3d9419' OR legacy_id='mon-jaghori-fc' OR lower(btrim(name))='jaghori fc') THEN RAISE EXCEPTION 'Jaghori identity exists; stop, do not duplicate'; END IF;
 IF (SELECT count(*) FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status='active' AND standings_eligible)<>14 THEN RAISE EXCEPTION 'Monday roster baseline changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status IN('draft','pending_review')) THEN RAISE EXCEPTION 'Review pending fixture work first'; END IF;
 IF EXISTS(SELECT 1 FROM public.standing_adjustments WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef') THEN RAISE EXCEPTION 'Reconcile standing adjustments before inheritance'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id='997291fd-33ff-40cc-9fd8-be732f6e07ca' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND legacy_id='mon-buckle-city' AND name='Buckle City' AND status='replaced' AND NOT standings_eligible AND profile_version=4 AND updated_at='2026-10-16T03:54:28.427266+00:00'::timestamptz) THEN RAISE EXCEPTION 'Outgoing/reinstated profile baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id='1d74c3b0-90ba-4304-aa68-b9681ea4bb9a' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND legacy_id='mon-declans-delinquents' AND name='Declan''s Delinquents' AND status='withdrawn' AND NOT standings_eligible AND profile_version=3 AND updated_at='2026-10-21T15:23:37.749877+00:00'::timestamptz) THEN RAISE EXCEPTION 'Outgoing/reinstated profile baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id='2368a5c2-7a91-484a-b201-fde870c85690' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND legacy_id='mon-hunger-fc' AND name='Gay Guys' AND status='withdrawn' AND NOT standings_eligible AND profile_version=4 AND updated_at='2026-10-21T15:23:37.749877+00:00'::timestamptz) THEN RAISE EXCEPTION 'Outgoing/reinstated profile baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.fixtures WHERE id='3765b565-c64c-4351-9c89-9522672fbf32' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND home_team_id='bd834936-1b8a-4dd7-9013-d4b792862b67' AND away_team_id='1d74c3b0-90ba-4304-aa68-b9681ea4bb9a' AND match_date='2026-10-12' AND kickoff_time='19:40:00' AND court=2 AND round_number=1 AND schedule_status='scheduled' AND publication_state='published' AND schedule_version=1 AND updated_at='2026-10-10T22:47:06.977969+00:00'::timestamptz) THEN RAISE EXCEPTION 'Inherited fixture baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.result_versions WHERE id='b3dbea6c-347a-40e1-a7f3-daa12ebb63b2' AND fixture_id='3765b565-c64c-4351-9c89-9522672fbf32' AND status='published' AND revision=1 AND home_score=1 AND away_score=6) OR (SELECT count(*) FROM public.result_versions WHERE fixture_id='3765b565-c64c-4351-9c89-9522672fbf32')<>1 THEN RAISE EXCEPTION 'Inherited result baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.fixtures WHERE id='e3471294-0d0b-4815-9fd1-2f52f9fa1aec' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND home_team_id='1d74c3b0-90ba-4304-aa68-b9681ea4bb9a' AND away_team_id='e5b8d7c3-89e1-430a-94b4-afd7b42cbe43' AND match_date='2026-10-19' AND kickoff_time='20:20:00' AND court=2 AND round_number=2 AND schedule_status='scheduled' AND publication_state='published' AND schedule_version=5 AND updated_at='2026-10-19T21:24:23.245474+00:00'::timestamptz) THEN RAISE EXCEPTION 'Inherited fixture baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.result_versions WHERE id='a34dcd6b-7b52-4638-8dbd-fdb7cddb0b91' AND fixture_id='e3471294-0d0b-4815-9fd1-2f52f9fa1aec' AND status='published' AND revision=1 AND home_score=7 AND away_score=9) OR (SELECT count(*) FROM public.result_versions WHERE fixture_id='e3471294-0d0b-4815-9fd1-2f52f9fa1aec')<>1 THEN RAISE EXCEPTION 'Inherited result baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.fixtures WHERE id='3f44938e-938e-4160-a978-6446b4d86151' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND home_team_id='2368a5c2-7a91-484a-b201-fde870c85690' AND away_team_id='8464062e-5897-4573-a075-d283236dd36c' AND match_date='2026-10-19' AND kickoff_time='21:00:00' AND court=1 AND round_number=2 AND schedule_status='scheduled' AND publication_state='published' AND schedule_version=3 AND updated_at='2026-10-19T21:24:23.245474+00:00'::timestamptz) THEN RAISE EXCEPTION 'Inherited fixture baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.result_versions WHERE id='a4e8f05a-9502-4324-8e84-a23b2096cbd2' AND fixture_id='3f44938e-938e-4160-a978-6446b4d86151' AND status='published' AND revision=1 AND home_score=4 AND away_score=12) OR (SELECT count(*) FROM public.result_versions WHERE fixture_id='3f44938e-938e-4160-a978-6446b4d86151')<>1 THEN RAISE EXCEPTION 'Inherited result baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.fixtures WHERE id='f21d315e-e106-4dd5-b47f-c676469407a2' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND home_team_id='2368a5c2-7a91-484a-b201-fde870c85690' AND away_team_id='ec502bdd-d24e-48cf-84fb-f27f11387fda' AND match_date='2026-10-12' AND kickoff_time='20:20:00' AND court=1 AND round_number=1 AND schedule_status='scheduled' AND publication_state='published' AND schedule_version=1 AND updated_at='2026-10-10T22:47:06.977969+00:00'::timestamptz) THEN RAISE EXCEPTION 'Inherited fixture baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.result_versions WHERE id='e896b677-ac85-4425-86e4-e41049833207' AND fixture_id='f21d315e-e106-4dd5-b47f-c676469407a2' AND status='published' AND revision=1 AND home_score=7 AND away_score=7) OR (SELECT count(*) FROM public.result_versions WHERE fixture_id='f21d315e-e106-4dd5-b47f-c676469407a2')<>1 THEN RAISE EXCEPTION 'Inherited result baseline changed'; END IF;
END $$;
CREATE TEMP TABLE monday_expansion_protected ON COMMIT DROP AS
SELECT 'results' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.result_versions r WHERE true
 UNION ALL SELECT 'fixtures' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.fixtures r WHERE id NOT IN('3765b565-c64c-4351-9c89-9522672fbf32','e3471294-0d0b-4815-9fd1-2f52f9fa1aec','3f44938e-938e-4160-a978-6446b4d86151','f21d315e-e106-4dd5-b47f-c676469407a2')
 UNION ALL SELECT 'teams' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.teams r WHERE id<>'997291fd-33ff-40cc-9fd8-be732f6e07ca'
 UNION ALL SELECT 'adjustments' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.standing_adjustments r WHERE true
 UNION ALL SELECT 'preferences' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.team_kickoff_preferences r WHERE true
 UNION ALL SELECT 'notes' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY team_id)::text,'[]')) hash FROM public.team_fixture_notes r WHERE true;
CREATE TEMP TABLE inherited_before ON COMMIT DROP AS SELECT id,to_jsonb(f)-'home_team_id'-'away_team_id'-'updated_at'-'schedule_version' preserved FROM public.fixtures f WHERE id IN('3765b565-c64c-4351-9c89-9522672fbf32','e3471294-0d0b-4815-9fd1-2f52f9fa1aec','3f44938e-938e-4160-a978-6446b4d86151','f21d315e-e106-4dd5-b47f-c676469407a2');
CREATE TEMP TABLE audit_before ON COMMIT DROP AS SELECT id,to_jsonb(a) preserved FROM public.admin_audit_log a;
INSERT INTO public.teams(id,competition_season_id,legacy_id,name,kit_colour) VALUES('0ad2ddbd-80e1-40f5-bb80-2e756a3d9419','62ce7ec9-459e-4acf-bec5-c6734a3199ef','mon-jaghori-fc','Jaghori FC','#1F9D55');
INSERT INTO public.team_fixture_notes(team_id,notes) VALUES('0ad2ddbd-80e1-40f5-bb80-2e756a3d9419','Organiser-approved 25 October 2026: distinct Jaghori FC identity, green kit, inherits Declan current-season two results. Requested 26 October at 21:00 against Buckle City. No additional availability restriction supplied; confirm any later change through Teams.');
UPDATE public.teams SET status='active',standings_eligible=true,profile_version=profile_version+1 WHERE id='997291fd-33ff-40cc-9fd8-be732f6e07ca';
UPDATE public.fixtures SET home_team_id=CASE WHEN home_team_id='1d74c3b0-90ba-4304-aa68-b9681ea4bb9a' THEN '0ad2ddbd-80e1-40f5-bb80-2e756a3d9419'::uuid ELSE home_team_id END,away_team_id=CASE WHEN away_team_id='1d74c3b0-90ba-4304-aa68-b9681ea4bb9a' THEN '0ad2ddbd-80e1-40f5-bb80-2e756a3d9419'::uuid ELSE away_team_id END WHERE id IN('3765b565-c64c-4351-9c89-9522672fbf32','e3471294-0d0b-4815-9fd1-2f52f9fa1aec');
UPDATE public.fixtures SET home_team_id=CASE WHEN home_team_id='2368a5c2-7a91-484a-b201-fde870c85690' THEN '997291fd-33ff-40cc-9fd8-be732f6e07ca'::uuid ELSE home_team_id END,away_team_id=CASE WHEN away_team_id='2368a5c2-7a91-484a-b201-fde870c85690' THEN '997291fd-33ff-40cc-9fd8-be732f6e07ca'::uuid ELSE away_team_id END WHERE id IN('3f44938e-938e-4160-a978-6446b4d86151','f21d315e-e106-4dd5-b47f-c676469407a2');
DO $$ BEGIN
 IF (SELECT count(*) FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status='active' AND standings_eligible)<>16 THEN RAISE EXCEPTION 'Expected 16 active eligible Monday teams'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.standings WHERE team_id='0ad2ddbd-80e1-40f5-bb80-2e756a3d9419' AND played=2 AND wins=1 AND draws=0 AND losses=1 AND goals_for=13 AND goals_against=10 AND points=3) THEN RAISE EXCEPTION 'Jaghori inheritance verification failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.standings WHERE team_id='997291fd-33ff-40cc-9fd8-be732f6e07ca' AND played=2 AND wins=0 AND draws=1 AND losses=1 AND goals_for=11 AND goals_against=19 AND points=1) THEN RAISE EXCEPTION 'Buckle inheritance verification failed'; END IF;
 IF EXISTS(SELECT 1 FROM inherited_before b JOIN public.fixtures f USING(id) WHERE b.preserved IS DISTINCT FROM to_jsonb(f)-'home_team_id'-'away_team_id'-'updated_at'-'schedule_version') THEN RAISE EXCEPTION 'Inherited fixture details changed'; END IF;
 IF EXISTS(SELECT 1 FROM audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE b.preserved IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit history changed'; END IF;
 IF EXISTS(SELECT 1 FROM monday_expansion_protected p JOIN (
 SELECT 'results' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.result_versions r WHERE true
 UNION ALL SELECT 'fixtures' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.fixtures r WHERE id NOT IN('3765b565-c64c-4351-9c89-9522672fbf32','e3471294-0d0b-4815-9fd1-2f52f9fa1aec','3f44938e-938e-4160-a978-6446b4d86151','f21d315e-e106-4dd5-b47f-c676469407a2')
 UNION ALL SELECT 'teams' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.teams r WHERE id<>'997291fd-33ff-40cc-9fd8-be732f6e07ca' AND id<>'0ad2ddbd-80e1-40f5-bb80-2e756a3d9419'
 UNION ALL SELECT 'adjustments' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.standing_adjustments r WHERE true
 UNION ALL SELECT 'preferences' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY id)::text,'[]')) hash FROM public.team_kickoff_preferences r WHERE true
 UNION ALL SELECT 'notes' kind,md5(coalesce(jsonb_agg(to_jsonb(r) ORDER BY team_id)::text,'[]')) hash FROM public.team_fixture_notes r WHERE true AND team_id<>'0ad2ddbd-80e1-40f5-bb80-2e756a3d9419'
 ) actual USING(kind) WHERE p.hash IS DISTINCT FROM actual.hash) THEN RAISE EXCEPTION 'Unrequested records changed'; END IF;
END $$;
COMMIT;
